WoWFQ[86522] = { t = "سپیده‌دم", d = "Turalyon مشغول سربازهاست. باید بفهماند این‌جا با چه چیزی روبه‌رو خواهند شد، دربارهٔ Lothraxion برایش بگوئیم...\n<Alleria shakes her head.>\nممنونم، <name>. حتی وقتی افکارم ابری می‌شود، تو هیچ‌وقت لرزه به خودت راه نمی‌دهی. برو، گزارشم را به Lor'themar برسان. من و Arator اوضاع را به Turalyon می‌گوییم.", o = { "به Silvermoon City سفر کن" }, c = "این مأموریتی ناممکن بود. قربانی‌هایی که شانسی برای جنگیدن به ما خریدند را فراموش نمی‌کنیم.\nبا این حال می‌دانم هر پیروزی‌ای لایق جشن نیست. وقتی جنگ آدم را میان دوستی و وظیفه مجبور به انتخاب می‌کند، خیلی‌ها از پسش برنمی‌آیند.\nفرصتی که به ما دادی را هدر نمی‌دهیم. حالا ضدحمله‌مان آغاز می‌شود." }
WoWFQ[86543] = { t = "تراس Magisters: بازگشت به خانه", d = "می‌دانیم داخل Voidstorm، آن‌سوی دروازهٔ عظیمش، خشکی هست. اگر خودمان را برسانیم، می‌توانیم جنگ را به سراغ Xal'atath ببریم.\nکلید را پیدا کرده‌ام. یادگاری است معروف به Cynosure of Twilight. سال‌ها ما را حیرت‌زده کرده با نشان دادن مسیرهای دست‌نیافتنی به بی‌نهایت ناشناخته‌ها.\nپژوهش‌هایم می‌گوید می‌توانم با آن راهی به سوی طوفان باز کنم.\nفقط یک مشکل هست: داخل Magister's Terrace است. و همان‌طور که می‌دانی، <name>، ما ren'doreiها در حال حاضر... آن‌قدرها هم در فهرست علاقه‌مندی‌هایشان نیستیم.", o = { "در Isle of Quel'Danas با Magister Umbric دیدار کن", "با Umbric صحبت کن تا ورود به follower dungeon آغاز شود", "Cynosure of Twilight را از Magisters' Terrace پس بگیر", "در Duskglow Gloriette در Silvermoon City با Magister Umbric دیدار کن." }, c = "می‌شد بهتر پیش برود.\nالبته هنوز Rommath من را نکشته. می‌شد بدتر هم بشود." }
WoWFQ[86549] = { t = "بی‌ترسی از تاریکی", d = "خلاف همهٔ شانس‌ها، رسیدیم.\nمی‌توانم راهی به درون طوفان باز کنم، اما پیوندش سست خواهد بود. فقط یک گروه کوچک از دروازه رد می‌شود.\nنمی‌دانیم آن‌سو چه در انتظارمان است. باید آماده باشیم.\nمی‌توانم با Cynosure خودمان را به Magisters' Terrace گره بزنم. اگر لازم شد فرار سریعی داشته باشیم، برمی‌گردانمتان همان‌جا.\nبیا--کمکم کن این افسون را تنظیم کنم.", o = { "Shadow Foci متصل شدند", "کمی بمان و به Lor'themar گوش کن", "ورود به دروازه" }, c = "این... این قدرت! هرگز Void را این‌طور حس نکرده بودم.\nهمه‌چیز را می‌بلعد. مثل وقتی در Telogrus زیر و رو شدیم...\nاما تو بر آن غلبه کردی. همه‌مان می‌توانیم. ما ren'dorei هستیم." }
WoWFQ[86733] = { t = "مذاکرات Silvermoon", d = "اگر بگویم رابطهٔ Silvermoon و Alliance معمولاً پرتنش و ناآرام است، کم‌گفته‌ام. ممنون که هر پیش‌داوری که ممکن بود داشته باشی کنار گذاشتی و به دفاع از Silvermoon و Sunwell نیرویی رساندی.\nنیروهای Xal'atath را فعلاً نگه داشته‌ایم، اما ماجرا خیلی دور از پایان است.\nدوست دارم در قدم‌های بعدیمان شریکیت کنم. مرا در Sanctum of Light ملاقات کن.", o = { "به Sanctum of Light برس", "در sanctum of Light در Silvermoon City با Lor'themar دیدار کن" }, c = "خوشحالم که رسیدی. شروع کنیم." }
WoWFQ[86769] = { t = "آخرین سنگر Light", d = "رسیدن تو امید را دوباره روشن کرد.\nنیروهای Xal'atath را از Sunwell عقب راندیم، اما هنوز Isle of Quel'Danas را آلوده‌اند و به‌نظر می‌رسد مشغول جمع شدن برای حملهٔ دیگری هستند در حالی که sin'dorei‌ها را شکار می‌کنند.\nباید به Vanguard of Light بپیوندیم.", c = "باید از این رویداد معجزه‌آسا برای برگرداندن موج علیه آشفتگی استفاده کنیم. نباید سست شویم." }
WoWFQ[86770] = { t = "قهرمانان Quel'Danas", d = "Lor'themar در Sunstrider Rise نقطهٔ تجمعی درست کرده، در حالی که غیرنظامیان آن‌جا به Silvermoon تخلیه می‌شوند، اما نیروهای Vanguard of Light در سراسر میدان نبرد پراکنده‌اند.\nباید یکی شویم تا با این لشکر حساب کنیم. با هم، می‌توانیم Xal'atath را شکست بدهیم و Sunwell را نجات دهیم.", o = { "Faerin Lothar را به خدمت بگیر", "Alonsus Faol را به خدمت بگیر", "Lothraxion را به خدمت بگیر", "در Sunstrider Rise با Lor'themar دیدار کن." }, p = "کمکی جمع کردی؟", c = "ممنونم، <name>. با این نیرو می‌توانیم بازماندگان را محافظت کنیم و تا قایق‌ها همراهی‌شان کنیم." }
WoWFQ[86780] = { t = "جایی که قهرمانان می‌ایستند", o = { "نیروهای Voidfront را در امتداد دیوارهای Parhelion Plaza معطل نگه دار." } }
WoWFQ[86805] = { t = "ساعت نیاز", d = "Turalyon مثل یک فرماندهٔ میدانی فکر می‌کند، نه مثل یک رهبر! قوم من، sin'dorei‌ها، در این جنگ‌های اخیر خیلی رنج کشیده‌اند. چند نفر دیگر باید به نام پیروزی او بمیرند؟\nلطفاً، <name>. هر غیرنظامی را که می‌توانی نجات بده و امن راهشان بده تا به قایق‌های Silver Landing برسند.\nهر نجات یافته یک پیروزی برای blood elfهاست.", o = { "غیرنظامی نجات یافت", "به سوی Silver Landing پیش برو" }, p = "کشتی‌ها هنوز جا دارند! هر چه می‌توانی نجات بده.", c = "غیرنظامیان سوار کشتی‌ها شدند. به‌زودی به امنیت Silvermoon می‌رسند." }
WoWFQ[86806] = { t = "بال‌های تابان", d = "نه! میزبان Xal'atath بالای تنگه دروازه باز کرده. موجودهای Void سرازیر شده‌اند و به کشتی‌های پناهجویان می‌تازند. باید از غیرنظامیان محافظت کنیم!\nآن dragonhawkها با Light قدرت گرفته‌اند. قدرت کافی برای شکست دادن هیولاهای Void و نجات غیرنظامیان فراری به تو می‌دهند.", o = { "سوار Empowered Dragonhawk شو", "Void Invaders کشته‌شده", "غیرنظامی درمانده نجات یافت" }, p = "کشتی‌های پر از پناهجوی sin'dorei هنوز در خطرند.", c = "کشتی‌ها تنگه را رد کردند و پناهجویان سالم به Silvermoon رسیدند. ممنونم، <name>. به قومم خدمت بزرگی کردی." }
WoWFQ[86807] = { t = "دروازه", d = "High Exarch به ما فرمان داد با Vanguard of Light او جمع شویم و به Devouring Host حمله کنیم. از به‌تعویق انداختن آن فرمان پشیمان نیستم، اما او غیبتم را دیده.\nبهتر است عجله کنیم و به بقیه ملحق شویم.", o = { "Tarenar", "Aponi", "به دروازهٔ شمال برس" }, c = "قهرمان، خوشحالم که می‌شنوم این‌همه sin'dorei جان به در بردند. با این‌که خلاف فرمان‌های من به Vanguard بود، تو زیر فرمان من نیستی. خوب از پسش برآمدی. Arator نه." }
WoWFQ[86811] = { t = "ریشه‌کنی اتریال‌ها", d = "<Name>! مأموریتی برایت دارم. در شمال‌شرق گروهی از etherealهای Shadowguard هستند.\nبه‌نظر می‌رسد مشغول غارت ساختمان‌ها هستند، اما ممکن است هر لحظه تغییر کنند. Vanguard نمی‌تواند اجازه بدهد در حین پیشروی از پهلو زده شویم. رهبرشان را بینداز و نیروهایشان را در هم بکوب تا ما با Host درگیر باشیم.", o = { "نیروهای Shadowguard کشته‌شده", "Norkonahl the Looter کشته‌شده" }, p = "مأموریت را کامل کردی؟", c = "عالی بود، <name>. می‌دانستم می‌توانم رویت حساب کنم." }
WoWFQ[86834] = { t = "بیرون راندن زاده‌های Void", d = "Devouring Host از هیولاهای اعماق Void ساخته شده، اما در نهایت یک ارتش است، با سرباز و فرمانده. در میان آن دریای void walkerها، موجودهایی متک‌وجهی می‌بینم.\nچه فرمانده باشند چه طلسم‌خوش‌یمنیِ Host، برداشتنشان از میدان به شکستن خطوطشان کمک می‌کند.", o = { "The Wasting کشته‌شده", "Blightclaw کشته‌شده", "Latrunculon کشته‌شده" }, p = "باید همهٔ فرماندهان void را شکست بدهیم.", c = "رفتن پشت خطوط ما بی‌احتیاطی بود! ایدهٔ Arator بود؟ این اواخر حسابی سرکش شده.\nببخشید، <name>. نباید این ماجراهای خانوادگی را لو می‌دادم. اعتراف می‌کنم کارهایت به Vanguard of Light در این نبرد کمک کرد." }
WoWFQ[86837] = { t = "دیدار در Sunwell", d = "مأمور شده‌ام به Vanguard of Light که از Sunwell محافظت می‌کند نیرو بدهم. کمک تو را می‌خواهم، البته نه فقط برای آن کار ساده.\nدوست مشترکمان، Arator،... گیر کرده. گیر در اندوه و خشمش بر سر آن درگیری تلخ با پدرش.\nمن فقط یک کشیش پیرِ زنده‌شده از مرگ هستم، اما دریافته‌ام که یک کوئست بهترین چیز برای برگرداندن یک paladin جوان به مسیر درست است.\nکمک می‌کنی؟", o = { "با Arator صحبت کن", "به Isle of Quel'Danas پرواز کن" }, p = "Sunwell شمال همین‌جاست، <name>. آن‌جا می‌بینمت.", c = "آخ... آن‌قدر نورانی است که چشم آدم درد می‌گیرد. تو هم همین را فکر می‌کنی، نه؟\nآه، قانعش کردی. ممنونم." }
WoWFQ[86848] = { t = "زره‌خانهٔ Light", d = "زره‌خانهٔ این‌جا سلاح‌ها و یادگارهای افسانه‌ای را نگه می‌دارد، برکت‌گرفته از قدرت Light به‌خاطر نزدیکی به Sunwell.\nحین این‌که ما زیر آتش Host گیر افتاده‌ایم، etherealها مشغول غارت این گنج‌ها هستند.\n<Name>، این یادگارهای مقدس را امن کن. بهترین سلاح‌های ما در برابر Void هستند. اگر لازم شد از آن‌ها برای دریدن این مهاجمان استفاده کن.", o = { "سلاح‌ها جمع شد" }, p = "یادگارها را امن کردی؟", c = "فقط برای غارت آمده بودند؟ یا دلیلی برای دنبال سلاح‌های Light داشتند؟\nاین حدس‌ها را می‌گذارم برای بعد. Vanguard همین حالا به این سلاح‌ها نیاز دارد. با آن‌ها، این Devouring Host را از Quel'Danas می‌رانیم!" }
WoWFQ[86849] = { t = "رهایی خشم", d = "<Name>، وقتش رسید! این شیاطین را تا Sun's Reach Harbor می‌رانیم! به دروازهٔ نفرین‌شدهٔ voidشان پس می‌زنیم و از این سواحل مقدس بیرون‌شان می‌کنیم!\nبه شرف Light! به شرف Azeroth!", o = { "به Turalyon در حمله به Voidwake Behemoth کمک کن", "Light را علیه Voidwake Behemoth جاری کن", "Vorasius را عقب بران" }, p = "تا وقتی از این سواحل بیرون‌شان نرانده‌ایم دست نکش!", c = "به Light قسم! نمی‌توانیم این نبرد را ببریم. تنها امیدمان Sunwell است!" }
WoWFQ[86850] = { t = "خورشید شکسته", d = "باید عقب‌نشینی کنیم! این نبردی نیست که ببریم. نه این‌طور.\nاما هنوز امیدی هست! Sunwell. Vanguard of Light را برای دفاع از آن به این‌جا آورد. تو را هم آورد، <name>. به تالار Sunwell عقب‌نشینی کن و تا می‌توانیم از آن دفاع کنیم.\nایمان دارم Light قصد نداشت امروز شکست بخوریم.", o = { "سوار Empowered Dragonhawk شو و فرار کن", "به Sunwell برس", "در ورودی Sunwell با Liadrin دیدار کن." }, c = "خدا را شکر. هر کس از Vanguard جان به در برد در تالار Sunwell است. حالا که رسیدی، می‌توانیم شروع کنیم." }
WoWFQ[86852] = { t = "آخرین پایداری Light", d = "تلاش‌هایمان برای جنگیدن با Devouring Hostِ Xal'atath شکست خورد. تنها امیدمان این است که باز هم Light را بخوانیم و اعتماد کنیم دلیلی داشته که این Vanguard را جمع کرده.\n<Name>، تو و Arator باید از Sunwell در برابر Devouring Host محافظت کنید. با این‌همه کمیتی که مانده، دیگر مدافع زیادی نداریم.\nایمان ما به Light نجاتمان می‌دهد.", o = { "با Liadrin صحبت کن تا آیین آغاز شود", "دفع نیروهای Void", "برکت‌گرفته از Sun's Ember", "Imperatus کشته‌شده" }, c = "باد Light برکتت دهد و از تو محافظت کند، <name>. دفاع تو از تالار Sunwell این معجزه را ممکن کرد.\nXal'atath را نشکستیم، اما حملهٔ Devouring Host را متوقف کردیم. حالا وقت داریم نفس تازه کنیم و بفهمیم برای شکستش باید چه کنیم." }
WoWFQ[86883] = { t = "کوچ دیوانه‌وار", d = "خبرهای Halduron نگران‌کننده است. اگر lightbloom روی سطح دیوانه شده، خطر خیلی سریع‌تر از چیزی رشد کرده که برایش آماده بودیم.\nباید فوراً به سمت Eversong برویم. در برابر هر تهدیدی به آفرینش Aln'hara می‌ایستم، چه این‌جا چه در دنیای بالا... و اگر لازم باشد، تنها.", o = { "از Emergency Rootway استفاده کن" }, c = "باورش نمی‌شود که وقتی ما پایین سر و کله می‌زدیم، Lightbloom در Eversong این‌قدر تهاجمی پخش شده باشد.\nبه همه‌اش لعنت! هر پیروزی که می‌بریم خطری تازه را لو می‌دهد." }
WoWFQ[86899] = { t = "ریشهٔ ماجرا", d = "rutaaniهایی که به Silvermoon حمله کردند از سرزمین من، Harandar، آمده‌اند. اما این آلودگی lightbloom چیز تازه‌ای است.\nوقت برگشتن پیش قومم است. به داوری‌شان می‌روم و کارهایم را توضیح می‌دهم.\nاگر lightbloom پخش شده باشد، باید خطر را به قومم خبر بدهم. اگر حوصله داری همراهی کنی، تو و دوست مصرت را از طریق rootwayها به Harandar می‌برم.\nوقتی آماده بودی خبرم کن.", o = { "با Orweyna صحبت کن.", "با دروازه به Harandar برو" }, c = "رسیدید. یک لحظه شک کردم برسی. نگران نباش--آن حالت تهوع رد می‌شود.\nدر ریشه‌های ژرف Amirdrassil ایستاده‌ایم. خانه‌ام آن‌سوست.\nببینیم چه استقبالی در انتظارمان است." }
WoWFQ[86903] = { t = "Arcantina", d = "<Name>، جایی هست که در جنگ دوم استفاده می‌کردیم؛ وقتی دلمان برای خانه تنگ می‌شد و لازم داشتیم Azeroth را به یاد بیاوریم. چیزی شبیه یک خلوتگاه و پناهگاه برای کسانی که جنگِ زیادی دیده‌اند--دردِ زیادی.\nبا گذر زمان، دوستان و متحدان را هم به آن‌جا بردیم. این سال‌ها اعضای Horde هم دعوت شده‌اند. اسمش را گذاشته‌ایم Arcantina.\nفکر می‌کنم Arator و تو هم به کمی استراحت در آن‌جا نیاز دارید. با این کلید دروازه‌ای بساز.", o = { "به Arcantina تله‌پورت کن", "Key to the Arcantina", "یک دور مهمان کن", "نوشیدنی‌ها سرو شد", "با Arator صحبت کن" }, p = "این واقعاً چه مکان خوبی است، این‌طور نیست، <name>؟", c = "چه سفری بود، <name>.\nخیلی چیزها از Alonsus و Sons of Lothar یاد گرفتم...\nو شاید بیشتر از همه، این‌که پدرم چه paladینی بود و چه paladینی از این به بعد خواهم بود." }
WoWFQ[86907] = { t = "لانهٔ پژواک‌ها", d = "درود، غریبه. من Elder Hagar هستم. اجازهٔ ماندن داری، تا وقتی که از آزمون‌های Den of Echoes رد شوی.\nAln'hara سرنوشتت را معین می‌کند و تو دربارهٔ قوم و رسوممان چیزهایی می‌آموزی.\nدر غارها به هم می‌رسیم.", c = "به Den of Echoes خوش آمدی. در غارهای آن‌سو نقاشی‌های باستانی‌ای است که قصهٔ haranirها را روایت می‌کند.\nشاید چیزی یاد بگیری، اگر زنده بمانی. باد Aln'hara یارت باشد." }
WoWFQ[88696] = { t = "ارگ بلعنده", d = "باید به Silvermoon برگردم، اما Turalyon به همهٔ قهرمانان تیزپا و تندرست Light فرمان داده در نقطهٔ تجمع بیرون Voidspire حاضر شوند.\nنیروهای لشکر بلعنده خواهند افتاد، <class>.\nیک‌جوری، به هر جوری.", o = { "با دروازه به Voidspire Muster Point برو", "به Muster Point رسیدی" }, c = "رسیدی. خوب است. می‌بینی که دشمن برای رسیدن ما آماده بود، حتی اگر ما نبودیم." }
WoWFQ[88709] = { t = "Voidspire", d = "بالاخره به سمت شکوه می‌تازیم و بر این موجود پست که خودِ Void را علیه ما به کار گرفته عدالت را اجرا می‌کنیم.\nامروز روزی است که نیروهای Xal'atath به داوری ما می‌رسند.\nحالا ساعت ضربه زدن است!\nبیا، به این دشمن پایان بدهیم.", o = { "ورود به رید Voidspire در حالت داستانی", "ورود به رید Voidspire", "رید Voidspire کامل شد" }, c = "مادر...؟\nپدر...؟" }
WoWFQ[88710] = { t = "کوچ به Quel'Danas", d = "قهرمان... رفیق... همین است.\nباید Darkwell را از چنگ L'ura دربیاوریم، یا به دست Void می‌افتیم. برای شانس دومی نیرو نداریم.\nمحکم بزن و درست بزن. حواست به پهلوهای متحدانت باشد و امروز را می‌بریم.", o = { "ورود به حالت داستانی", "رید March on Quel'Danas کامل شد" }, c = "روز را بردیم، اما فهمیدن این‌که با Darkwell چه باید کرد ممکن است کمی طول بکشد.\nاگر یک گروه متخصص در چاه‌های قدرت در سراسر Azeroth باشد، همان الف‌هایی است که امروز به کمکم جمع کردی. دور هم جمع می‌شوند و مسیر بعدی را تعیین می‌کنند.\nفعلاً؟ از پیروزی لذت ببر. شجاعت و شرف را نمود کردی و به جنگیدن کنارت افتخار می‌کنم." }
WoWFQ[88719] = { t = "صدایی از Light", d = "<Name>، برگزیده شده‌ای.\nارتش Voidِ Xal'atath بر Sunwell فرود آمده. ما ایمانمان را به Light بسته‌ایم و Light هم بزرگ‌ترین قهرمانان Azeroth را فراخوانده.\nبه این فراخوان جواب بده و در برابر Devouring Host بایست! سرنوشت Quel'Danas و دنیا در دستان تو است.", o = { "با تصویر Liadrin صحبت کن یا از Light's Summon استفاده کن", "به Quel'Danas سفر کن", "Light's Summon" }, c = "Light تو را خوانده، <name>. امیدمان به قهرمانان Azeroth و Vanguard of Light است!" }
WoWFQ[88769] = { t = "نبرد پل", d = "متحدان الف‌مان رسیدند. وقت آن است که جنگ را به سراغ Darkwell ببریم.\nنیروهای Xal'atath پل را در دست دارند و اخیراً برای تقویت موضع‌شان به اسکله رخنه کرده‌اند. باید اسکله را پس بگیریم، نیروی دریایی‌مان را به کار بیندازیم و با حمله‌ای ترکیبی پل را بگیریم.\nآماده‌ای، <name>؟", o = { "نبرد پل برده شد" }, c = "خوب جنگیدی، <name>. اما کارمان هنوز تمام نشده." }
WoWFQ[89012] = { t = "راهی امن", d = "باید غیرنظامیان را نجات بدهیم و به کشتی‌ها برسانیم، اما راه اسکله به دست موجودی پست و گرسنه بسته شده.\nاگر می‌خواهیم قومم را نجات دهیم، باید راه تخلیه را باز کنیم. نمی‌شود گذاشت تنها سرشان کنند.", o = { "Gloomstress کشته‌شده" }, p = "هنوز آن Void بلعنده راه را بسته؟", c = "ممنونم، <Name>. این مأموریت‌های نجات به‌ندرت به‌سادگی به‌نظر می‌رسند. همیشه یک تهدید دیگر هست که حواست بهش نبوده." }
WoWFQ[89271] = { t = "پسرم", d = "یک لحظه، <Name>. کار شخصی دارم. می‌خواهم پسرم، Arator، را پیدا کنی. عضو Silver Hand است، یک paladin ماهر.\nمی‌دانم فراخوانده شده. ایمانش قوی است. Light می‌خواهد او این‌جا بجنگد، در برابر Xal'atath.", o = { "کمک Arator را جلب کن", "به Light's Spire برس", "در Sunstrider Rise با Turalyon دیدار کن." }, p = "پسرم را پیدا کردی؟", c = "پیدایش کردی؟ خدا را شکر!\nحواس‌پرتی را نمی‌توانیم تحمل کنیم. Arator باید همین‌جا با نیروهای جمع‌شده باشد، کاملاً متمرکز بر یورش به Xal'atath." }
WoWFQ[89507] = { t = "پیشکش‌های فراوانی", o = { "در برداشت‌های فراوانی 20000 امتیاز جمع کن." } }
WoWFQ[90690] = { t = "تاخت Vanguard", d = "Turalyon گزارش می‌دهد Vanguard of the Light آمادهٔ یورش به سنگرگاه Xal'atath است.\nکاش می‌شد در این تاخت همراهتان بودم. نیروهای تحت‌فرمانم را همین‌جا نگه می‌دارم تا دفاع از Sunwell و Silvermoon سر پا بماند وقتی شما جنگ را به دشمن می‌برید.\nدر Voidstorm جمع شوید، به Voidspire بروید و به این دشمن بزرگ پایان بدهید. شکار خوش.", c = "خوب، <name>! برای تاخت رسیدی." }
WoWFQ[90718] = { t = "درخواست Arcantina", d = "آه، <name>!\nشنیدم دعوت‌نامهٔ همیشگی به... Arcantinaِ Archmage Khadgar داری؟\nمی‌روی آن‌جا و این نامه را به Archmage می‌رسانی؟ برای حجم افسون‌های تله‌ماسی که از من خواسته‌اند باید reagent تهیه کنم.\nMagister's Terrace تا این اواخر منبع خوبی بود، اما واقعاً به Kirin Tor نیاز دارم که چند مادهٔ کمیاب به من قرض بدهد.", o = { "Request for Reagents" }, p = "قهرمان؟ چیزی برای من دارید؟", c = "هم. ببینیم.\nچشم Warpstalker، یک الک اتری- \nصفرای Jormungar؟! می‌خواهد با آن چه کند؟ و من به آخرین ویال‌هایم رسیده‌ام.\nخب، چاره‌ای نیست. همین که جمع شد برای Oculeth می‌فرستم. در این مدت، خودت را دور میخانه سرگرم کن، قهرمان." }
WoWFQ[90724] = { t = "آسمان شکسته", d = "همهٔ آن آدم‌ها. ارتشمان. قهرمانانمان. رهبرانمان.\nرفته‌اند.\nاینجا بی‌پناهیم. طناب Umbric نجاتمان داد، اما باید مطمئن شویم از این ماجرا زنده می‌مانیم. به Lor'themar گزارش بده و بگو در Voidspire چه گذشت. من Umbric را به امنیت می‌رسانم و این‌جا هر چه می‌توانم می‌فهمم.", c = "روز تاریکی است.\nدیده‌بان‌هایم را می‌فرستم تا بیشتر بفهمند در دنیا چه می‌گذرد، در حالی که با نیروهای باقی‌مانده از Silvermoon City دفاع می‌کنیم.\nآماده باش، قهرمان. به‌زودی به تو نیاز داریم." }
WoWFQ[90748] = { t = "Quel'Danas", o = { "پیش از دروازه‌های Quel'Danas با Arator دیدار کن." } }
WoWFQ[90749] = { t = "دشمن مشترک ما", d = "<Liadrin lowers her voice, speaking only to you.>\nدو انتخاب داریم. یا به حرف‌های Amani‌ها گوش بدهیم یا راه خودمان را با زور باز می‌کنیم.\nترجیح می‌دهم با Zul'jarra برای عبور مذاکره کنم، اما اگر مذاکره به‌هم بریزد، آماده باش.\nفعلاً، دنبال من بیا.", o = { "با Lady Liadrin از دروازهٔ Amani عبور کن." }, c = "باید اعتراف کنم که... غافلگیر شدم که Zul'jarra اجازهٔ عبور داد. سال‌ها از آخرین باری که من یا هر کس از Eversong پایش را به این‌سوی مرز گذاشت گذشته.\nحواست جمع باشد. موقعیت حساسی است. شاید لازم باشد کارهای بیشتری برای جلب اعتمادشان بکنیم.\nاما به Amaniها پشت نکن." }
WoWFQ[90777] = { t = "سوخت رساندن به شعله", d = "قهرمان، Sunwell فعلاً سر پاست، اما Vanguard بخش عمدهٔ نیروهایش را به Voidstorm فرستاده.\nLady Liadrin کمک تو را در Sunwell خواسته است.", o = { "در Sunwell با Liadrin صحبت کن", "با فرماندهٔ Koruth Mountainfist صحبت کن", "برکتی از War Chaplain Senn بگیر", "با فرماندهٔ Venel Lightblood تمرین کن" }, p = "دل‌گرم‌کننده است که فرماندهانمان این‌قدر مشتاق بردن جنگ به سراغ دشمن‌اند.", c = "فعلاً پابرجاییم، <name>. هر چه زودتر با Xal'atath در Voidspire روبه‌رو شویم، زودتر همهٔ این‌ها پشت سرمان می‌گذرد." }
WoWFQ[90861] = { t = "آن‌ها که جا مانده‌اند", d = "در پی ویرانی Xal'atath، آن چه از نیروهایمان مانده در Darkwell جمع شده‌اند تا تصمیم بگیرند با بقایای Void چه کنند.\nنمی‌توانیم حضور این‌همه انرژی تاریک را تحمل کنیم. بعضی از بزرگ‌ترین جادوان و دانش‌پژوهان‌مان فکر می‌کنند راه‌حلی پیدا کرده‌اند، اما کمک تو را می‌خواهیم.\nلطفاً، در اولین فرصت به Arator در Darkwell بپیوند.", c = "ممنون که آمدی. شایسته است که تو هم در این روز کنار ما باشی." }
WoWFQ[91087] = { t = "گزارش‌های برگشته", d = "به Silvermoon می‌روم اما... به این‌جا برمی‌گردم تا به Zul'jarra مشورت بدهم.\nحس می‌کنم گذاشتم گذشته و پیش‌داوری‌هایم راه داوری‌ام دربارهٔ Amaniها را ببندند. می‌شود گفت hash'ura بودن کفاره‌ای مناسب است اما... حس می‌کنم کشیده می‌شوم بمانم، شاید برای کمک به Zul'jarra در هدایت قومش به سمت loaها.\nبا تو به Silvermoon می‌آیم تا گزارش را برسانم--و واکنش Lor'themar را ببینم.\nاگر همین حالا برویم، ممکن است به‌موقع برگردیم برای... جشن.\n<A small smile cracks Liadrin's usually stoic face.>", c = "<Lor'themar raises an eyebrow and frowns slightly. You can tell he is fighting back exasperation and anger.>\nاین یک... چرخش خیلی غیرمنتظره است. و مطمئنم هنوز چیزهای بیشتری جلوی چشم ما رخ خواهد داد." }
WoWFQ[91095] = { t = "شکار: Magister Sunbreaker (معمولی)", d = "روزی Magister شریف Silvermoon بود، سوگند خورده بود Quel'Thalas را با هر قیمتی محافظت کند. از فرقه جدا شده و حالا به شیوهٔ خودش انتقام می‌جوید.\nچیزی از خودم در او می‌بینم.\nبرایم بکشش.", o = { "شکارت را شکار کن", "Magister Sunbreaker کشته‌شده" }, c = "بوی شومینه می‌دهی. امیدوارم برایت زیادی دشوار نباشد؟" }
WoWFQ[91096] = { t = "شکار: Magistrix Emberlash (معمولی)", d = "شکار Magistrix Emberlash را دنبال کن و بکشش.\nپیشرفت شکار با کامل کردن فعالیت‌های Prey، کوئست‌های جهانی، rareها و گنج‌های منطقهٔ انتخابی‌ات پیش می‌رود.", o = { "شکارت را شکار کن", "Magistrix Emberlash کشته‌شده" } }
WoWFQ[91097] = { t = "شکار: Senior Tinker Ozwold (معمولی)", d = "شکار Senior Tinker Ozwold را دنبال کن و بکشش.\nپیشرفت شکار با کامل کردن فعالیت‌های Prey، کوئست‌های جهانی، rareها و گنج‌های منطقهٔ انتخابی‌ات پیش می‌رود.", o = { "شکارت را شکار کن", "Senior Tinker Ozwold کشته‌شده" } }
