WoWFQ[91099] = { t = "شکار: Mordril Shadowfell (معمولی)", d = "Void چیز بی‌وفایی است، مثل آب. خردمندان آن را در فاصله‌ای محترمانه نگه می‌دارند، هیچ‌وقت آن‌قدر نزدیک لبه نمی‌رقصند. نادان‌ها شیرجه می‌زنند و در همان حال غرق می‌شوند.\nMordril برای خودش و هر کس دور و برش خطری است، آن‌قدر در وسواس خودش گم شده.\nکاری کن دیگر برای این سرزمین تهدید نباشد.", o = { "شکارت را شکار کن", "Mordril Shadowfell کشته‌شده" }, c = "من از مرگ یک هم‌نوع الف هیچ‌وقت لذت نمی‌برم.\nخب.\nاین بار نه." }
