WoWFQ[91117] = { t = "شکار: Knight-Errant Bloodshatter (معمولی)", d = "death knightها در بهترین حالت‌شان ماشین‌های کشتاری ناپایداری‌اند. Knight-Errant Bloodshatter هر سوگند و پیمانی که ظاهراً هم‌نوع‌هایش را به پله‌های پایین جامعهٔ متمدن گره می‌زد رها کرده و کاملاً یاغی شده.\nدارد به بار و تهدیدی تبدیل می‌شود.\nدرد و اندوهش را جمع کن تا از این موقعیت ناگوار بهترین استفاده را ببریم.", o = { "شکارت را شکار کن", "Knight-Errant Bloodshatter کشته‌شده" }, c = "بوی جسد می‌دهی و آن نگاه دوری در چشمانت است؛ از آن نگاه‌ها که بعد از زیادی وقت گذراندن کنار death knightها می‌افتد. حدس می‌زنم شکارت موفقیت‌آمیز بود؟" }
