WoWFQ[91121] = { t = "شکار: Thornspeaker Edgath (معمولی)", d = "این یکی واقعاً مسئله‌ای خاردار است. Thornspeaker Edgath اسمی برای خودش ساخته با این‌که قدرت‌های دروئیدی‌اش را نه برای حفظ Azeroth، بلکه برای پیچاندن نیرویش هم علیه دشمنانش هم تماشاگران بی‌گناه به کار می‌گیرد. به هیچ چیز احترام نمی‌گذارد مگر حیوانی باشد یا در خاک بروید.\nوقتش رسیده این خار را بچینیم.", o = { "شکارت را شکار کن", "Thornspeaker Edgath کشته‌شده" }, c = "به خار و سوزن انگشتانم، یک قهرمان فروتن از این راه می‌آید..." }
