WoWFQ[91274] = { t = "بریدن Void", d = "High Exarch خط دفاعی چشمگیری درست کرده. تعداد فعلی Devouring Host را نگه می‌دارد. اما پشت خطوط، پایه‌های void را می‌بینم. آن‌ها Devouring Host بیشتری فرا می‌خوانند و Vanguard of Light را زیر و رو می‌کنند.\nقدرتشان آن‌قدر خطرناک است که نتوانیم مستقیم نابودشان کنیم، اما اگر بتوانیم sentinelهایی را که در حملهٔ اول افتادند دوباره فعال کنیم، خودشان برایمان پایه‌ها را نابود می‌کنند.", o = { "Sentinelها فعال شدند", "Void-Breach Pylon نابود شد" }, p = "برای نابود کردن پایه‌های Void باید همهٔ sentinelها را فعال کنیم.", c = "با نابودی آن پایه‌های Void، Devouring Host ضعیف شده. شاید شانسی برای بردن داشته باشیم." }
WoWFQ[91546] = { t = "برای تغییر کردن", d = "یک مطلب حل‌نشده مانده...\n<Astre reaches into their pocket and reveals the worn letter you had unpackaged alongside Hieron's journal. They run their fingers over it with a pensive expression.>\nHieron می‌خواست این به او برسد. باید بداند برایش چه شد.\nاین مال خودم است. باز هم Silvermoon... خب، وقتی برگشتم می‌بینمت، <name>.", o = { "با Umbric صحبت کن", "Riftblade Astre در Silvermoon پیدا شد", "با Astre صحبت کن", "چای Ghostflower دم شد", "چاقی قرض گرفته شد", "برش‌های Sunfruit بریده شد", "Sunfruit به چای Ghostflower اضافه شد", "چای Ghostflower چشیده شد" }, p = "حداقل به دیدن پدر و مادرم نمی‌روم.", c = "خوشحالم که این کار را انجام دادم. ممنون که همراهم آمدی.\nبرگردیم پیش بقیه در Voidstorm، <name>." }
WoWFQ[91787] = { t = "پایان سفر", d = "Light شکل‌های زیادی دارد. اما حالا می‌دانم برای من چه معنایی دارد و چطور می‌خواهم به کارش ببرم.\nمن فقط یک سلاح مثل پدرم نیستم، و نمی‌توانم مثل Dezco تمام‌وکمال در خدمت باشم.\nاما می‌توانم از آدم‌ها در برابر شرارتی که تهدیدشان می‌کند محافظت کنم. همین حالا، آن شرارت Xal'atath و Devouring Host اوست.\nباید برگردیم پیش Lor'themar و هر کاری لازم است برای شکست Void بکنیم.\nفراتر از آن، می‌بینم محافظت از دیگران با Light مرا کجا می‌برد.", c = "ممنون، <name>، که به مدافعانمان در Sunwell نیرویی رساندی.\nبه‌نظر می‌رسد Arator هم ماجراهایش را جمع و جور کرده و برای هر چه پیش می‌آید آماده است. خوب است که هر دوی شما دوباره متمرکز جنگ با Void هستید.\nArator مرد خوبی است. خوشحالم که در این درگیری او را از دست ندادیم." }
WoWFQ[91828] = { t = "لطفی برای شیر", d = "نامه‌ای برایم آمد. بدون مهر، بدون اسم. فقط کاغذی تا شده و خطی که هر جا ببینمش می‌شناسم.\nخیلی نمی‌گفت. او هیچ‌وقت حرف اضافه نمی‌زند.\nخانواده‌اش را سال‌هاست می‌شناسم. وقتی دست به دامن می‌شوند، جواب می‌دهم.", o = { "نامه خوانده شد", "در Zul'Aman با Valeera دیدار کن" }, p = "بله؟", c = "مسیر را زیر نظر داشته‌ام. رفت‌وآمد کم است، دست‌کم فعلاً." }
WoWFQ[91918] = { t = "دلوها: دو بار اندازه بگیر، دوبار ببر", d = "خوب کار کردیم و فراری‌ها را به امنیت رساندیم، اما به خودت مغرور نشو که همه‌شان را آزاد کرده‌ایم.\nزمزمه‌هایی شنیده‌ام از جایی که از آن برای شکستن کسانی که وفاداری‌شان زیر سؤال است استفاده می‌کنند. مکانش معلوم نیست، اما می‌دانم از کجا باید شروع کنم.\nاگر تند عمل کنیم، شاید بقیه را هم پیدا کنیم، پیش از آن‌که فرقه تصمیم بگیرد نگه‌داشتن‌شان ریسک زیادی است.\nنزدیک محل به من بپیوند. تیغ‌هایت تیز و قدم‌هایت سبک.", o = { "ورود به دلوی Twilight Crypts", "فراری‌های عذاب‌کشیده آزاد شدند", "دلوی Twilight Crypts کامل شد" }, p = "خودت را نگه دار.", c = "این‌ها همه‌اش بودند. آفرین." }
WoWFQ[92520] = { t = "پس‌لرزهٔ Darkwell", d = "Sunwell--نه... Darkwell زیر و رو شده.\nموجودات زادهٔ Void مناطقی را گرفته‌اند که بزرگ‌ترین قهرمانان Light ما تا آخرین نفس سر جایشان ایستادند.\nقهرمان، می‌توانی Quel'Danas را گشتی بزنی؟ بازمانده‌ای پیدا می‌کنی؟ با این نشان‌ها علامت‌شان بزنی، جادوان ما می‌توانند تک‌تک‌شان را تله‌پورت کنند. باید هر چه می‌توانیم نجات‌شان دهیم.", o = { "Anduin Wrynn بازیابی شد", "Prophet Velen بازیابی شد", "Faerin Lothar بازیابی شد", "سایر بازماندگان بازیابی شدند" }, c = "خیلی کم‌اند. اما کسانی که نجات دادی از امید من هم بیشتر بود." }
WoWFQ[92895] = { t = "دعوت Hagar", d = "Hagar پیامی دارد که باور دارد الف‌ها و ترول‌های Azeroth باید همگی بشنوند. به رهبران قبیله‌های الف و ترول پیغام داده به Harandار بیایند.\nمن آمده‌ام از blood elfها دعوت کنم به ما بپیوندند، اما تو هم باید آن‌جا باشی. تو این‌همه مسیر با ما بودی.\nRootwayهای Silvermoon سریع‌ترین راه است.", o = { "از Rootway به Harandar برو", "به نشست برس" }, c = "دیگر طول نمی‌کشد." }
WoWFQ[92904] = { t = "بازگشت به Zul'Aman", d = "این قصه را از بچگی شنیده‌ام! Amani‌ها کم‌شمار بودند و با این حال جنگیدند! با خالص‌ترین اراده پیروز شدند!\nOrweyna می‌گوید رؤیاها دروغ نمی‌گویند. عمو فکر می‌کند جزئیات نبرد ممکن است گم شده باشد. اگر بفهمند دروغ بوده، دیگر همه‌چیزِ Amani بودن زیر سؤال می‌رود.\n<Zul'jan scowls.>\nباید حقیقتش را پیدا کنم. عمو می‌گوید اگر کسی بداند، loaها می‌دانند. loaها تا حالا چیزی از این نگفته‌اند، اما باید از جایی شروع کرد.\nوقت رفتن به خانه است.", o = { "از Rootway به Zul'Aman برو", "به Talonstrike Terrace برس" }, c = "چرا عمویم این‌قدر بی‌نظم است؟" }
WoWFQ[92924] = { t = "آن‌سوی مه", d = "با loaها قدرتمندیم. بدون loaها هم هنوز Amani‌ایم. خویشاوندانمان را پس می‌گیریم.\nLiadrin به‌زودی با نیروهای کمکی به ما می‌پیوندد و جنگجویانم تشنهٔ انتقام‌اند.\nجای تعلقی نیست. به‌خاطر قومم و به‌خاطر Zul'jan.", c = "این ویرانه‌های یک شهرک Amani است.\nباید بقایای آبادی همین‌جا باشد، پیش از آن‌که پل فرو بریزد و جزیره قربانی نفرین شود.\nاما اگر حتی loaها هم نمی‌توانند بیایند این‌جا، این tortollanها چطور زنده مانده‌اند؟ چرا این‌جایند؟" }
WoWFQ[93420] = { t = "داوری Lor'themar", d = "باید به Lor'themar بگوییم این‌جا چه گذشت. در Silvermoon به من بپیوند.\nاما Zul'jarra... به زمان نیاز دارد. به قومش نیاز دارد و قومش به او.\nاز این ماجرا جان به در می‌برد. مطمئنم. باید!", o = { "در Silvermoon City به Lor'themar برگرد", "کمی بمان و به Zul'jarra و Lady Liadrin گوش کن" }, c = "<Lor'themar regards you stiffly as you recount your efforts in Zul'Aman.>\nخوشحالم که... Amani‌ها توانستند با کمک تو و Liadrin خودشان سر و کله با این «Ula'tek» پیدا کنند.\nامیدوارم از این به بعد کمتر خبرشان را بشنویم." }
WoWFQ[93890] = { t = "Midnight: فراوانی", d = "ترول‌های Zul'Aman قدرتشان را از loaها می‌گیرند: ارواح باستانی که به کسانی که ارج می‌نهند قدرت می‌بخشند. این برکت‌ها بسته به ذات loa و سرسپردگی پیروانش، می‌توانند شگفت‌انگیز یا مرگبار باشند.\nزمزمه‌هایی هست از Loa of Abundance‌ای که در Zul'Aman خانه دارد؛ می‌گویند برکتش به لایق‌ها رفاه می‌دهد.\nپیدایش کن، بفهم چه چیزی او را می‌راند و ببین آیا لطفش به کار ما می‌آید.", o = { "رویدادهای فراوانی کامل شد" }, p = "به loaها احترام بگذار، اما از قدرتشان بترس.", c = "با Loa of Abundance دیدار کردی. باد هدیه‌هایش به‌دردت بخورد." }
WoWFQ[93931] = { t = "فراوانیِ ثروت", o = { "ثروت برای Loa of Abundance برداشت کن.", "یک رویداد فراوانی را کامل کن" } }
WoWFQ[94361] = { t = "زندگی فراوان", o = { "هر رویداد فراوانی را یک بار کامل کنید. آن‌ها در Eversong، Zul'Aman، Harandar و Voidstorm قرار دارند.", "برداشت در Watha'nan Crypts", "برداشت در Loaknit Den", "برداشت در Floaret Grotto", "برداشت در Abundant Voidburrow" } }
WoWFQ[94382] = { t = "دردسرهای آیینی", d = "رک بگویم، برای پیشروی به سمت خطرهای مختلفی که در این مکان‌های آیینی می‌بینیم، چند درس و چند هدف دیده‌بانی برایمان در نظر گرفته‌ام.\nمحل یکی از این آیین‌ها را روی نقشه‌ات علامت زده‌ام. مواظب باش، جادوهایی که در این مکان‌ها بافته می‌شود می‌تواند حتی استوارترین جنگجو را زیر و رو کند.", o = { "گزارش‌های مکان‌های آیینی بررسی شد", "مکان آیینی کامل شد" }, p = "موفق بودی؟", c = "امیدوارم حالا خطر آیین‌های بزرگ را جدی بگیری.\nمی‌ترسم این مکان‌ها هر چه بیشتر بررسی‌شان کنیم و چالش‌های تازه سر راه بیاید، خطرشان هم بیشتر شود." }
WoWFQ[94519] = { t = "در Light چه امیدی؟", d = "از وقتی حوادث تلخ Voidspire رخ داد، Arator رنج می‌کشد. از خودش می‌گوید، یا تنها در Dawnwell دعا می‌کند.\nهمه‌مان از دست دادن Alleria و Turalyon رنج می‌بریم، اما Arator به‌تازگی دوباره به آن‌ها رسیده بود، بعد از آن جنگ طولانی با Burning Legion.\nنگرانم اگر زیادی تنها با افکارش بماند، از این ماجرا همان آدمی که بود بیرون نیاید.\nبرویم به Dawnwell و حالش را بگیریم.", o = { "در Dawnwell با Magister Umbric صحبت کن" }, c = "اگر Light جواب نمی‌دهد، پس باید راه دیگری پیدا کنم.\nTwilight's Blade حتماً چیزی می‌داند از این‌که Xal'atath کجا رفته یا نقشهٔ بعدی‌اش چیست. اگر بتوانیم وادارشان کنیم حرف بزنند، می‌توانیم جلویش را بگیریم.\nباید به این باور داشته باشم." }
WoWFQ[94520] = { t = "شور دوباره در Deatholme", d = "با این‌که هنوز نمی‌دانیم Xal'atath کجا رفته یا Alleria و Turalyon زنده‌اند یا نه، هنوز می‌توانیم دنبال اطلاعات برویم.\nRiftblade Maella مرا از وضعیت فرقه‌گراهای Twilight به‌روز نگه می‌دارد. دارند قدرت و تعداد جمع می‌کنند و به‌نظر می‌رسد دنبال... چیزی می‌گردند. حالا وقت اقدام است.\nبرویم به ویرانه‌های Deatholme و ببینیم چرا این فرقه‌گراها دوباره جان گرفته‌اند.", c = "فکر می‌کردم این‌همه جنگیدن تعداد Twilight's Blade را کم کرده باشد، اما ظاهراً هیچ اثری نداشته.\nحتی الان بیشترشان! مشغول چه کاری‌اند؟" }
WoWFQ[94527] = { t = "فضای تهی", d = "Arator مثل کسی که جن زده باشد دنبال Antenorian پرید. آن‌قدر با این جنگ صلیبی کور شده که... باید نمی‌داند برای کسی مثل او پریدن کورکورانه به Void چقدر خطرناک است.\nنه، باید آرزبان فکر کنیم. وضعیت را تحلیل کنیم.\nراهی برای دانستن آن‌سوی آن دروازه نداریم.\nاما باید برویم داخل. باید Arator را پیدا کنیم.", o = { "وارد ناشناخته شو", "از Null Space جان به در ببر" }, c = "چه... چه اتفاقی افتاد؟" }
WoWFQ[94531] = { t = "مادر که باشد، پسر هم", d = "<Arator quietly seethes.>\nباید به Lor'themar بگوییم چه فهمیده‌ایم. نه به این دلیل که بخواهم دنبال Xal'atath را رها کنم، اما این مهم است.\nبیا، Zul'Aman را ترک کنیم و به Silvermoon برگردیم.", c = "<Lor'themar shakes his head.>\nArator قوی است. گاهی سرکش. اما باید روی چیزی که همین الان جلوی ماست تمرکز کنیم.\nبا مرگ Ula'tek، چیز بدتری در مرزهایمان سر برآورده. باید آماده باشیم.\n<Lor'themar's expression hardens.>\nبا تمام نیرویی که می‌توانیم جمع کنیم." }
WoWFQ[95021] = { t = "شکار: Janoa the Fang (کابوس)", d = "شکار Janoa the Fang را دنبال کن و بکشش.\nپیشرفت شکار با کامل کردن فعالیت‌های Prey، کوئست‌های جهانی، rareها و گنج‌های منطقهٔ انتخابی‌ات پیش می‌رود.", o = { "شکارت را شکار کن", "Janoa the Fang کشته‌شده" } }
WoWFQ[95022] = { t = "شکار: Kursak the Coiled (کابوس)", d = "شکار Kursak the Coiled را دنبال کن و بکشش.\nپیشرفت شکار با کامل کردن فعالیت‌های Prey، کوئست‌های جهانی، rareها و گنج‌های منطقهٔ انتخابی‌ات پیش می‌رود.", o = { "شکارت را شکار کن", "Kursak the Coiled کشته‌شده" } }
WoWFQ[95023] = { t = "شکار: Batani the Scaled (کابوس)", d = "شکار Batani the Scaled را دنبال کن و بکشش.\nپیشرفت شکار با کامل کردن فعالیت‌های Prey، کوئست‌های جهانی، rareها و گنج‌های منطقهٔ انتخابی‌ات پیش می‌رود.", o = { "شکارت را شکار کن", "Batani the Scaled کشته‌شده" } }
WoWFQ[95024] = { t = "شکار: Kadani the Claw (کابوس)", d = "شکار Kadani the Claw را دنبال کن و بکشش.\nپیشرفت شکار با کامل کردن فعالیت‌های Prey، کوئست‌های جهانی، rareها و گنج‌های منطقهٔ انتخابی‌ات پیش می‌رود.", o = { "شکارت را شکار کن", "Kadani the Claw کشته‌شده" } }
WoWFQ[95197] = { t = "راه دور", d = "یک فاجعه را دور زدیم، اما تهدید Kith'ix هنوز پابرجاست.\nZul'jarra در یک چیز حق دارد. معنی ندارد ارتشی را به رویارویی مستقیم بفرستیم. اگر در اوج قدرتمان بود، شاید--اما به لطف Xal'atath، از آن خیلی فاصله داریم. یک گروه کوچک و نخبه باید بتواند از دریا خودش را به Atal'Utek برساند... اگر بتوانیم تا آن موقع به‌جای چنگ انداختن به هم، با هم کنار بیاییم.\nبگو ببینم، <name>. با قایق‌ها چطور؟", c = "هنوز شروع نکرده‌ایم و همین حالا دارد گلوی همدیگر را می‌گیریم. این قرار است سفری پرمخاطره باشد." }
WoWFQ[95203] = { t = "گره‌هایی که می‌بندند", d = "نُه جنگجو در برابر کل دسته‌ای خفته از هیولاهای باستانی. شانس‌مان همین‌طور هم کم است، نباید خودمان هم در گردنه پاهای هم را بزنیم.\nسفر دریایی کمی طول می‌کشد. شاید فرصتی باشد برای ساختن کمی اعتماد قبل از نبرد.", o = { "سوار قایق شو و به Atal'Utek بادبان بزن", "برای تله‌پورت به Atal'Utek با Liadrin صحبت کن" }, p = "<Liadrin looks a mite queasy.>\nواقعاً هوس این کار را ندارم.", c = "دست‌کم یک‌تکه رسیدیم.\nکار دلهره‌آوری پیش روی ماست، <name>. اما ایمان دارم. کمیم، اما Mightyایم.\nتا وقتی از پشت سر هم مراقبت کنیم، شاید امروز پیروز شویم." }
WoWFQ[95811] = { t = "در پیروزی، اندوه", d = "Liadrin...\nکاش وقت عزاداری داشتم، <name>، اما Silvermoon باید بداند این‌جا چه گذشت... هم پیروزی و هم تراژدی. باید بروم تدارک ببینم و مردم را جمع کنم.\nممنون می‌شوم تو هم آن‌جا باشی.", o = { "در Gardens of Remembrance در Silvermoon با Lor'themar دیدار کن" }, p = "این یک پیروزی است، اما با این‌همه از دست دادن...", c = "ممنون که آمدی، <name>. این آسان نخواهد بود، اما با حضورت آسان‌تر می‌شود.\nاین... مال تو. به Salandria پیشنهادش دادم، اما نپذیرفت و گفت تو بگیرش." }
WoWFQ[96004] = { t = "شکار: تهدیدی خزنده", d = "حسش می‌کنی، <name>؟\nداریم تماشا می‌شویم.\nنمی‌دانم از سوی چه کسی و برای چه هدفی، اما به‌نظر می‌رسد... تلاش‌هایمان توجه تازه‌ای جلب کرده. برو بیرون و میدان را گشتی بزن.\nبیایید زره‌پوشی این تازه‌واردان را بسنجیم.", o = { "Batani، Kadani، Janoa یا Kursak کشته شد در حالت Nightmare" }, p = "چکمه‌هایت هنوز زیادی تمیز است برای کسی که کارش را کرده باشد.", c = "موجودات مار؟ چه لذت‌بخش." }
WoWFQ[96080] = { t = "حملهٔ Void", d = "گزارش‌هایی رسیده از حمله‌های void تازه در Eversong Forest و Zul'Aman.\nلازم است فوراً بروی یکی از این حمله‌ها را بررسی کنی. آخرین مکان گزارش‌شده از سوی دیده‌بان‌هایمان را روی نقشه‌ات علامت می‌زنم.", o = { "اختلال در Void Strike" }, p = "چه گزارشی داری؟", c = "می‌دانستم تو آدمِ همین مأموریتی. اطلاعات تو برای چیزی که حالا به آن Void Assault می‌گوییم حیاتی بود. نیروهای Void، Twilight's Blade، Etherealها و Naga در سراسر منطقه به ما حمله می‌کنند.\nکامل مشخص نیست، اما گزارش‌های اولیه می‌گویند گروه‌ها با هم هماهنگ نیستند.\nباید تجهیزاتت را کامل کنیم و دوباره بفرستمت بیرون!" }
WoWFQ[96224] = { t = "معمای Magisters", d = "Magisters' Terrace خانهٔ یادگارهای مرموز فراوانی است.\nمیان آن‌ها یادگاری است که روزی در مرکز پیگیری دانش جادویی ما بود. چند سال پیش، آن یادگار به خواب فرو رفت.\nبعد از جان گرفتن دوبارهٔ Dawnwell، این شیء شروع به تکان خوردن کرد. با بردنش به Lycaneum برای مطالعه، یادگار آشفتگی را بر کتابخانه ریخت.\nباور دارم تخصص یکتای تو ممکن است برای آرام کردن این آشفتگی مفید باشد.", o = { "با دروازه به Magisters' Terrace برو", "در کتابخانهٔ Magisters' Terrace با Rommath و Umbric دیدار کن" }, p = "حرف‌های زیادی برای زدن داریم.", c = "<Rommath eyes you up and down for a moment.>\nپس تو همان کمکِ بیرونی هستی که Magister Umbric فراخوانده، این‌طور نیست؟ به‌خیر.\nشاید تو اولین عضو Alliance باشی که به Sunstrider Omnium نگاه می‌کند... اگرچه روزهای بهتری هم داشته.\nسال‌ها خواب و سکوت، بعد ناگهان بیداری در قالب آشوبی جادویی.\nکارهای زیادی هست و پرسش‌های زیادی باید جواب بگیرد." }
WoWFQ[96225] = { t = "معمای Magisters", d = "چند دههٔ اخیر، زیر تالارهای Magisters' Terrace، یادگاری خفته بود.\nروزی فانوس دانش برای Magisters بود، اما بی‌هشدار چند دهه پیش ساکت شد.\nبعد از تولد دوبارهٔ Dawnwell، یادگار بیدار شد. وقتی برای مطالعه به Lycaneum برگرداندیمش، آشفتگی را بر کتابخانه ریخت.\nکمک و سکوتِ تو بیشترین قدر را دارد.", o = { "با دروازه به Magisters' Terrace برو", "در کتابخانهٔ Magisters' Terrace با Rommath و Umbric دیدار کن" }, c = "آه، <name>. به‌نظر می‌رسد Grand Magister در انتخاب یاورهایش قابل پیش‌بینی شده. بسیار خوب.\nپیش تو Sunstrider Omnium ایستاده. یادگاری که دو دهه ساکت و بی‌جان بود... تا بیداری ناگهانی‌اش همان اوایل.\nآشوبی که به راه انداخته تهدیدی برای کل Magisters' Terrace است و شاید فراتر.\nبا کمک تو، شاید بتوانیم مهارش کنیم." }
WoWFQ[96228] = { t = "برج سایه‌ها", d = "باز و باز، Dar'Khan به شکلی از اشکال به ما جن زده است.\nباورش نمی‌شود Omnium هم قربانی جنون او شد...\nاگر واقعاً Void Magicule را از Omnium جدا کرده باشد، جای شکی نیست که جایش را خوب پنهان کرده.\nحدسی دارم که از کجا باید شروع کنیم.\nدر Dawnstar Spire در Eversong Woods به من بپیوند.", o = { "در Dawnstar Spire با Umbric صحبت کن", "Focusing Anchor گذاشته شد", "لنگر اول متصل شد", "لنگر دوم متصل شد", "لنگر سوم متصل شد", "لنگر آخر متصل شد" }, p = "باورش نمی‌شود که میان آن کشتار و خون‌ریزی، Dar'Khan به بی‌حرمتی به یادگاری هم پرداخت که خودش خواهان مطالعه‌اش بود...", c = "با اتصال و پایدار شدن لنگرها، می‌توانم امن با تپش ضعیفی که دور و بر حس می‌کنیم هم‌آوا شوم.\nبا کمی شانس، Void دقیقاً لو می‌دهد که این تپش از کجاست.\nو Dar'Khan که شناخته‌ایم، قطعاً نوعی نگهبان دوم یا تدبیر محافظت جا گذاشته.\nخودت را آماده کن، <name>." }
WoWFQ[96232] = { t = "بازگشت به Omnium", d = "خب، حالا که تکه‌ای را که Dar'Khan دزدیده بود پس گرفتیم، یک قدم به بازسازی Omnium نزدیک‌تریم.\nامیدوارم ماجرایت با Rommath کم‌دردسرتر بوده باشد؟\nوقتی آماده بودی، به Magister's Terrace برگرد. هر چه این‌جا جا مانده را جمع می‌کنم و به‌زودی به تو می‌پیوندم.", o = { "با دروازه به Magisters' Terrace برو", "به Omnium برگرد" }, p = "بدون شبکهٔ گمشده و رمز-کلید، Omnium به همان شکل از کنترل خارج می‌شود.", c = "فکر کنم باید ممنون باشیم که Dar'Khan تصمیم گرفت این‌همه رازش را در آن مکان نفرین‌شده دفن کند.\nحتی فکرش را هم نمی‌کنم اگر Void Magicule را در Deathholme پنهان کرده بود و به دست Scourge یا Twilight's Blade می‌افتاد چه می‌شد.\nفقط یک کار مانده، <name>." }
WoWFQ[96441] = { t = "طلب دانش، هفتهٔ 2 از 5: جادوی آیینی", d = "ذهن اهالی Magisters' Terrace را مشغول یک پرسش کرده:\nاگر جادو می‌تواند جادوی دیگر را آلوده و مشتبه کند، Dawnwell چه بلایی سر خطوط ley که از آن منشعب می‌شوند می‌آورد؟\nبا پرسش، آزمایش می‌آید.\nمکان‌های آیینی در Quel'Thalas از خطوط ley برای سوخت جادویشان استفاده می‌کنند.\nاین مکان‌ها را به هم بریز و نمونه‌هایی از جادوی ارکان که پیدا می‌کنی بیاور.", o = { "مکان‌های آیینی به هم ریخته شد", "Ritualized Arcana" }, p = "همه داریم می‌پرسیم Dawnwell چه اثری روی خطوط ley در Quel'Thalas می‌گذارد.\nفرآوردهٔ جانبی این مکان‌های آیینی شاید نشان بدهد این جادوهای بیرونی چقدر ژرف رخنه کرده‌اند.", c = "به‌نظر می‌رسد نظریهٔ Magister Umbric درست بود. آیین‌ها تار و پود ارکان را داغان کرده‌اند؛ هم اضافه‌شارژش کرده‌اند هم تمام‌وکمال تخلیه‌اش کرده‌اند.\nشاید روایت‌های مشابهی داخل Omnium ثبت شده باشد.\nMagistersهایی که مسئول مطالعهٔ این نمونه‌ها هستند کار زیادی در پیش دارند.\nحین انتظار، نگاهی به رون‌های تازه‌ای که برایت ترسیم کرده‌ایم بینداز." }
WoWFQ[96442] = { t = "طلب دانش، هفتهٔ 3 از 5: تاخت بر خطوط ley", d = "متأسفانه بیشتر نمونه‌های قابل اندازه‌گیری با انرژی افراطی مکان‌های آیینی محو شدند.\nاگر می‌خواهیم جادوهای مختلفی را که به خطوط ley نشت می‌کنند درست اندازه بگیریم، نمونه‌هایی از منبعی گسترده‌تر و کم‌تمرکزتر لازم داریم.\nگفته‌اند Farstriderها همچنان دارد حمله‌های void را در سراسر Quel'Thalas عقب می‌راند.\nاز هر یک از این نیروهای مهاجم، انرژی ley انباشته برایم بیاور.", o = { "Dark-Ley Coalescence" }, p = "ارکانی که از مکان‌های آیینی آوردی نشانه‌ای از فرسودگی افراطی انرژی ley بود.\nRommath نظریه دارد جادویی که در این حمله‌ها به کار می‌رود سنجه‌ای مشابه می‌دهد، بدون سوختگی تخلیه‌شده.", c = "چه لکه‌های void داشته باشد چه گره خورده با رشته‌های بیگانهٔ ارکان، انرژی leyای که آوردی قرائت دقیق‌تری به ما می‌دهد.\nدر حالت ایده‌آل می‌توانیم نوع اثر این جادوها روی خطوط ley‌مان را معین کنیم تا بفهمیم برای Dawnwell چه معنایی دارد.\nبعداً به ما سر بزن. این‌جا کار هست و رون‌های تازه برای بررسی." }
WoWFQ[96444] = { t = "طلب دانش، هفتهٔ 5 از 5: جادوی فرازمین", d = "با این‌که primessense‌ای که آوردی کاتالیزور عالی بود، عاملی را لو داد که در حساب‌هایمان نداشته بودیم.\nذات بیگانهٔ جادوی void و اتریال که در حمله‌هایشان به کار می‌رود با آزمایش ناسازگار بود.\nبرای پیشرفت، نمونه‌ای از جادویشان لازم داریم. نه از حمله‌ها در Quel'Thalas، بلکه از سرچشمهٔ حمله‌ها.\nگفته‌اند این دشمنان از پایگاه‌های دور از دنیا می‌تازند. موفق باشی، <name>.", o = { "پاره‌ای از جادوی Void یا Arcane بیگانه بازیابی کن", "کوئست‌های جهانی را در Val یا Naigtal کامل کن" }, c = "<Rommath narrows his eyes at the swirling mote of magic you brought him before glancing at Umbric.>\nنمی‌پرسم چطور توفیق جستن چنین... منبع بیگانه‌ای از جادو را داشته‌ای، اما دقیقاً همین را برای ادامهٔ آزمایش‌هایمان لازم داریم.\nنقش تو به‌عنوان یک جوینده برای تلاش‌های ما بی‌بدیل بود. در عوض، من و Umbric آخرین رون‌هایی که برایت کنار گذاشته بودیم را حک کردیم.\nببین." }
WoWFQ[96466] = { t = "شکار: جزیرهٔ رنج", d = "چیزی این موجودها را به قلمرو ما می‌راند.\nیکی از کارآمدترین خدمتکارانم را به این «Isle of Fangs» فرستاده‌ام. برو و ببین از پس این لانهٔ مار چه برمی‌آیی. در هر مأموریت دیگری همراهت می‌آمدم، البته--اما همین‌جا می‌مانم.\nاین جزیره حسابی مکان رعب‌آوری به نظر می‌رسد.\nولی خوش بگذرد، اهل فن.", o = { "با ادامه دادن Curse of Ula'tek Isle of Fangs را باز کن" }, p = "از این‌جا متنفرم.", c = "مار.\nچرا حتماً باید مار باشد؟" }
WoWFQ[96503] = { t = "شکار: کابوسی شبح‌گونه", d = "به‌نظر می‌رسد دیده‌بانی‌هایت ثمری داشته. این قدرت می‌تواند برای هدف باشکوه‌مان بهترین نعمت باشد.\nبه Atal'Utek برگرد و جادویش را برای هدف ما مکش کن.", o = { "پذیرش Curse of the Isle بدون شکار فعال Prey", "بررسی Haunted Brazier در حال نفرین بودن", "جمع کردن Ossified Relicها در Coiled Isle در حال نفرین بودن", "احضار و کشتن Terror of the Isle در یک Haunted Brazier" }, p = "هنوز هستی؟", c = "امیدوارم چیزی حسابی زشت با خودت برنگردانده باشی." }
WoWFQ[96523] = { t = "افسانه‌ای زنده", d = "این سربازها--خیلی کوچک‌اند که دوران پیش از یاری loaها را یادشان باشد. پس loaها نمی‌توانند بیایند این‌جا. و بعد؟\nبگذار افسانه‌ای را تعریف کنم که به زمان پیش از یاری loaها به قوم ما برمی‌گردد. شاید شنیده باشی؟ یا شاید بخواهی خودت زنده‌اش ببینی...", o = { "برای آغاز قصه با Kehiah صحبت کن" }, p = "به قصه گوش بده... یا شاید خودت زندگی‌اش کن!", c = "ببین تو را! دیگر قهرمان نیستی، فقط یک روستایی سادهٔ ترول. حالا که جا افتادی، قصه را شروع کنیم." }
WoWFQ[96525] = { t = "شکار: ژرف‌تر از توان ما", d = "این از آن چیزی است که برایش آماده نبودم.\nدروازه‌ای به سمت Sanctum باز می‌کنم.\nمنتظر می‌مانم این مارمولک‌های لعنتی از پیچیدن دور من خسته شوند، بعد دنبالت می‌آیم. خواهشاً از من خیرخواهی کن.", o = { "دروازه به Astalor's Sanctum گرفته شد" }, p = "البته که ارواح هم هست.", c = "بوی ترس و سراسیمگی می‌دهی.\nشگفت‌انگیز است." }
WoWFQ[96532] = { t = "شکار: مراقبت از پیشخدمت", d = "روش‌هایم شاید به گوش بعضی‌ها بی‌رحم و غیرمتعارف برسد، اما به سلامت کسانی که زیر دستم خدمت می‌کنند واقعاً اهمیت می‌دهم.\nاکثر اوقات.\nAttendant Ethrandil برای هدف ما محترمانه خدمت کرد. لطفاً به او بگویید می‌تواند پیش من برگردد.\nاین کف‌ها همین اواخر حسابی کثیف‌تر شده‌اند...", o = { "دروازه از Astalor's Sanctum به Coiled Isle را استفاده کن" }, p = "امیدوارم پیشخدمتم با چیز حسابی زشتی درگیر نشده باشد. کمکِ خوب این روزها به‌زحمت پیدا می‌شود...", c = "تو زنده‌ای! من هم زنده‌ام!\nهنوز." }
WoWFQ[96539] = { t = "آخرین چاره", d = "خیلی، خیلی وقت پیش، دهکده‌ای بود که خشکسالی سختی بر آن چیره شد. محصولات نمی‌روییدند و زمین خشک شد. کل دهکده گرسنه بود! روستاییان پیش یک ترول رفتند--Jeytha--و از او لطفی خواستند.\nدر این قصه، تو خودِ Jeytha هستی--حالا برو ببین آن روستاییان گرسنه چه می‌خواهند!", o = { "با Hungry Villager صحبت کن", "ردپا دنبال شد" }, p = "قصهٔ ما با Jeytha آغاز می‌شود--نه داناتر، نه قوی‌تر و نه مهربان‌تر از همین که هست!", c = "سفرش را همان‌طور که خواستند رفت، اما آه! آن وسط جلوتر چیست؟" }
WoWFQ[96540] = { t = "دستان قوی", d = "Jeytha در مسیر به روباهی برخورد که lynxها پشتش را داشتند. او مهربان بود، بی‌ترس و قوی--پس تصمیم گرفت به آن روباه کمک کند.\nحالا برو به آن lynxها بگو بیرون بیفتند!", o = { "Prowling Lynxها را بران", "دنبال روباه زبردست برو" }, p = "به قصه گوش بده... یا شاید خودت زندگی‌اش کن!", c = "خب ببین! به‌نظر می‌رسد آن روباه چیز بیشتر از یک روباه معمولی است، نه؟" }
WoWFQ[96541] = { t = "ذهن قوی", d = "آن روباه پیر زبردست روباه معمولی نبود! حرف زد، دوید و منتظر ماند Jeytha به او برسد. حالا او چه می‌خواست از Jeytha؟\nبهتر است با او حرف بزنی و بفهمی!", o = { "ببین روباه زبردست چه می‌خواهد", "نعمت دومت را از روباه زبردست بخواه" }, p = "به قصه گوش بده... یا شاید خودت زندگی‌اش کن!", c = "ببین--دقیقاً به همان جایی برگشت که شروع کرده بود، و همه زنده‌اند! Jeytha به‌اندازه‌ای که قوی بود، زبردست هم بود!" }
WoWFQ[96543] = { t = "ریشهٔ بقای", d = "حالا که به نقطهٔ شروع برگشت، Jeytha فهمید نمی‌تواند آن سفر را تکرار کند. اما روستاییان گرسنه چه؟ چطور زنده می‌مانند؟\nJeytha چند ایده داشت... اگر روستاییان گوشش را بگیرند. برو ببین چه می‌گوید!", o = { "با Hungry Villager صحبت کن", "Withered Root", "Critter Meat" }, p = "لطفاً، Jeytha! نگذار دهکده‌مان از گرسنگی بمیرد!", c = "خیلی هم نیست، اما با همین‌ها حتماً می‌توانیم زنده بمانیم. ممنون از خردت، Jeytha!" }
WoWFQ[96544] = { t = "سوزاندنِ شجاعانه", d = "سال‌ها گذشت و او آن نعمت سوم را به کار نگرفت. سالی، دسته‌ای از dragonhawkهای خشمگین چشم--و شعله‌--شان به دهکده افتاد. پسرش گرفتار شده بود، خانه‌شان آتش می‌گرفت!\n«می‌توانم از نعمتم استفاده کنم،» فکر کرد Jeytha، «اما چرا از نعمتم استفاده کنم وقتی می‌توانم از قدرتم استفاده کنم؟»\nبرو قدرتت را به آن dragonhawkها نشان بده و آن پسر را نجات بده!", o = { "Enraged Dragonhawk کشته‌شده", "Teho نجات یافت" }, p = "قصهٔ ما با Jeytha آغاز می‌شود--نه داناتر، نه قوی‌تر و نه مهربان‌تر از همین که هست!", c = "فیو! همه‌اش یک روز کار عادی برای Jeytha--و هنوز هم آن نعمت سوم دستش بود!" }
WoWFQ[96545] = { t = "صدای قوی", d = "سال‌ها گذشت و Jeytha هنوز آن نعمت سوم را به کار نگرفته بود. سالی، گروهی از راهزنان به دهکده آمدند که می‌خواستند هر چه داشتند بدزدند.\n«می‌توانم از آن نعمت سوم استفاده کنم،» فکر کرد Jeytha، «اما چرا از آن نعمت استفاده کنم وقتی می‌توانم از صدایم استفاده کنم؟»\nبرو آن راهزنان را قانع کن--و اگر گوش نکردند، از قدرتت استفاده کن و فکرشان را عوض کن!", o = { "راهزن خشمگین با حرف آرام شد" }, p = "آن راهزنان یک‌جوری حتماً گوش می‌گیرند!", c = "Jeytha خردمند بود و راست گفت--و صدایش آن راهزنان را آرام کرد جایی که ضربه‌ها نتوانسته بودند." }
WoWFQ[96546] = { t = "قلب قوی", d = "سال‌ها گذشت و Jeytha حس کرد وقتش رسیده. زندگی بلندی داشت؛ پر از سختی اما هنوز خوش. اما وقتی Jeytha به آخرین روزهایش رسید، آن روباه پیر زبردست ظاهر شد.\n«صبر کن!» گفت. «هنوز نمی‌توانی بروی!»\nحالا آن روباه چه می‌خواهد؟ برو با او حرف بزن و بفهم!", o = { "ببین روباه چه می‌خواهد", "پیشنهاد نعمت چشم‌به‌راه را رد کن", "نعمت سومی بخواه", "برای پایان قصه با Kehiah صحبت کن" }, p = "به قصه گوش بده... یا شاید خودت زندگی‌اش کن!", c = "روباه زبردست، شکرگزارِ نعمت Jeytha، دوید رفت. و Jeytha کمی بعد از آن، استخوان‌های پیرش را ترک کرد--آرام‌تر، اما به‌همان اندازه راضی." }
WoWFQ[96708] = { t = "به Voidstorm و آن‌سوتر!", d = "شاید زیاد به نظر نیاید، اما متحدانی که جمع کرده‌ایم باید کافی باشند.\nوقت راه افتادن است.\nنیروهایمان در Howling Ridge جمع می‌شوند. انرژی‌های Voidstorm به ما اجازه می‌دهد راه این دنیاها را باز کنیم.\nآن‌جا می‌بینمت. چیزی این‌جا هست که هنوز برای مأموریت لازم دارم.", o = { "از دروازهٔ Silvermoon به Voidstorm برو", "با Riftblade Maella صحبت کن" }, c = "شاید ائتلافی غیرمعمول از متحدان باشد، اما هر کدام تخصصی دارند که ما در جنگ با دشمن به آن نیاز داریم.\nحتی Decimus هم نمی‌تواند انکارش کند.\nآخرین قطعهٔ لازم را به دست آورده‌ام، Cynosure of Twilight، تا شکاف را به جایی باز کنم که این اتریال‌ها و نیروهای void از آن عمل می‌کنند.\nآماده‌ای، <name>؟" }
WoWFQ[96728] = { t = "مطالعات مکان آیینی: هفتهٔ 1 از 3", d = "بعد از این‌که گزارش دادی صف‌هایشان را خالی کرده‌ای، به فکر فرو رفتم.\nاز چه چیزی برای جذب اعضا استفاده می‌کنند؟ آیا آن‌قدر متعصب‌اند که رهبرانشان؟\nمی‌پرسم آیا می‌توانیم با نابودی تعداد بیشتری از صف‌هایشان ارادهٔ جنگیدنشان را بشکنیم. می‌ترسم برای اطمینان بیشتر از یک نمونه لازم باشد.", o = { "مکان آیینی Tier 6 با نیروهای کمکی کامل شد" }, c = "آیین دوم هم مثل اولی محافظت می‌شد؟\nخب، نمی‌توانم بگویم غافلگیر شدم. آدم‌های خودمان هم راحت منصرف نمی‌شوند و رهبرانشان خیلی قانع‌کننده‌اند. جاه‌طلبی این گروه‌ها را بارها و بارها عقب رانده‌ایم.\nآن چه آوردی را مطالعه می‌کنم و به‌زودی مأموریت تازه‌ای برایت دارم." }
WoWFQ[96729] = { t = "مطالعات مکان آیینی: هفتهٔ 2 از 3", d = "مأموریت بعدیت را دارم، <race>. لازم است مقاومت این نعمت‌های خبیث و اوبلیسک‌های تاریکشان را مطالعه کنی.\nجادو را حسابی متمرکز می‌کنند و تنوع نعمت‌ها جالب است. اما به دادهٔ بیشتری نیاز دارم.\nوقتی مکان آیینی بعدی را به هم ریختی، باید این کار را با حضور این نعمت‌های خبیث انجام بدهی.", o = { "مکان آیینی Tier 6 با نعمت‌های خبیث کامل شد" }, p = "چه کشف کردی؟", c = "این بار یکنواختی به سود ماست. خب، دست‌کم به سود من.\nگزارش تو چند حفره در فهم من از این‌که اوبلیسک‌ها چطور با نیروهایشان تعامل و اتصال دارند پر می‌کند.\nباز هم ممنون، برایت درسی تازه آماده می‌کنم." }
WoWFQ[96730] = { t = "مطالعات مکان آیینی: هفتهٔ 3 از 3", d = "فکر می‌کنم در آستانهٔ یک کشف بزرگ هستم. این آیین‌های اخیر جادویی را به کار می‌برند که قبلاً نشنیده بودم: خاکسترهای پرقدرتی که از انرژی نیروهای خودشان برای تقویت رهبرشان استفاده می‌کنند.\nاگر این آیین‌ها را به هم بریزی و یافته‌هایت را به من گزارش کنی، شاید بتوانم این جادو را برای خودمان به کار بگیرم. این‌طور به من نگاه نکن. البته روی شیاطین خودم. باورت شد منظورم سربازهایی مثل تو بود؟\nبرای چنین آزمایش‌هایی خیلی زود است. با یافته‌هایت برگرد!", o = { "مکان آیینی Tier 6 با خاکسترها کامل شد" }, c = "هم... یادداشت‌هایت آن‌قدر جزئی نیست که دوست داشتم. کاش وقتی سراغ رهبرشان رفتی تعداد بیشتری ازشان را فعال گذاشته بودی...\nالبته شاید همان اتفاق به مرگ تو و از دست رفتن داده‌ها ختم می‌شد، پس تحمل می‌کنم. این امیدوارکننده است.\nآه، هنوز هستی. آره، قول داده بودم بابت کمک به این مسیر پژوهشی پاداشی بهت بدهم.\nاگر بخواهیم این‌ها را در ترکیب‌های خاص مطالعه کنیم... خب، آن برای زمان دیگری است." }
WoWFQ[96731] = { t = "مطالعات پیشرفتهٔ مکان آیینی: هفتهٔ 4 از 6", d = "همین که رفتی ایده‌ای به ذهنم رسید.\nصف‌هایشان را کم کرده‌ایم و دیده‌ایم که می‌توانند نیروی کمکی احضار کنند.\nمی‌خواهم حد ذخیره‌هایشان را بسنجیم.\nاگر عهده‌دار این مجموعه چالش شوی، قول می‌دهم یک کلید دیگر برای خزانه بدهمت.", o = { "مکان آیینی Tier 6 با نیروهای کمکی و زنگ‌های خطر کامل شد" }, c = "این دارد ثمری می‌دهد. با این‌که در آخرین تلاش‌هایت برای به‌هم ریختن آیین تعداد سربازهایشان را نگه داشتند، در آن دروازهٔ زنگ آخر فقط چند ثانیه کند شدند.\n<race>، فقط باید فشار را نگه داریم. مطمئنم به‌زودی می‌شکنند. بعد باید سراغ این اوبلیسک‌ها برویم." }
WoWFQ[96732] = { t = "مطالعات پیشرفتهٔ مکان آیینی: هفتهٔ 5 از 6", d = "حالا که ذخیره‌های سربازشان را آزمودیم، تمرکزمان روی اوبلیسک‌های تاریک و همین نعمت‌هایی است که می‌دهند.\nاین کار بررسی دقیق می‌خواهد و قطعاً یعنی حین کاوش در مکان با گشت‌های بیشتر روبه‌رو می‌شوی. برای کسی مثل تو چندان سخت نیست.\nفقط ازشان فرار کن... یا اگر لازم شد حسابشان کن.", o = { "مکان آیینی Tier 6 با نعمت‌های خبیث و گشت‌ها کامل شد" }, c = "این خوب است؛ اوبلیسک‌های تاریک از چیزی که فکر می‌کردم مقاوم‌ترند. دوباره غافلگیر شدی، نه؟ البته که این خبر خوبی است؛ فکر کنم تقریباً آن‌قدر یاد گرفته‌ام که بتوانم خودم چیزی شبیهشان بسازم.\nحالا، نمی‌بینی چه نعمت بزرگی خواهد بود؟ همیشه هم بحث محروم کردن یا نابود کردن ابزارهای دشمن نیست. اغلب یادگیری است که چطور ابزارشان را علیه خودشان... یا تهدیدهای دیگر به کار ببریم." }
WoWFQ[96733] = { t = "مطالعات پیشرفتهٔ مکان آیینی: هفتهٔ 6 از 6", d = "به خانه برگشتی، شاگرد ستارهٔ من. یک مأموریت آخر برایت دارم و این یکی چالشی است.\nاین خاکسترهایی که در آیین‌هایشان به کار می‌برند. تا حالا در بازسازی‌شان یا پیدا کردن راه مقابله باشان موفق نشده‌ام.\nیک ایدهٔ آخر دارم که می‌خواهم امتحان کنی. گزارش دادی که تظاهرات جادویی از ارواح جادوان دیدی. نظریه‌ام این است که با حضور هر دو چالش، شاید راهی برای خنثی شدنشان به‌وجود بیاید.", o = { "مکان آیینی Tier 6 با خاکسترها و تظاهرات کامل شد" }, p = "کار کرد؟", c = "کار نکرد؟ خب، حیف شد. ارزش امتحان داشت؛ این چیزی است که اگر ادامه بدهی مطالعهٔ آیین‌ها یاد می‌گیری. گاهی فقط باید چیزها را امتحان کرد.\nگاهی به هیچ جا نمی‌رسد، گاهی هم می‌توانی باهاش غولی شیطانی احضار کنی تا دشمنانت را بکوبد. دومی را به تو توصیه نمی‌کنم. احتمالاً نه برای تو خوب پیش می‌رود نه برای دشمنانت.\nخب، دیگر چیزی از تو لازم ندارم. کلید را بگیر و تشکر من را هم!" }
WoWFQ[97625] = { t = "فراوانی شکوهمند", d = "Loa of Abundance شاید یکی از چهار بزرگ نباشد، اما پیروانش قطعاً متدین‌ترین‌اند.\nخودت سراغش برو. در شمال Zul'Aman نزدیک Halazzi's Temple پیدایش می‌کنی، اما شنیده‌ام مکان‌های برداشت هم در Eversong Woods و Harandar و حتی سرزمین Void از طریق آن دهان آسمانی غول‌آسا درست کرده است.\nاگر هیچ، پاداش‌هایی که می‌بخشد شکوهمند است--به لایق‌ها، دست‌کم.", o = { "یک رویداد فراوانی را کامل کن" }, p = "loa را پیدا کردی، hash'ura؟", c = "هیس! بالاخره Dundun را دیدی.\nحتی کوچک‌ترین‌ها گاهی از بزرگ‌ترین loaها هستند!" }
WoWFQ[98831] = { t = "هزارتو", d = "خبر توسعه‌ای نگران‌کننده در Eversong به من رسید.\nسردابه‌ای باستانی از قوم من به‌زور شکسته شده. نمی‌دانیم چه کسی جرئت چنین کاری را پیدا کرده، اما ما نیروی بررسی‌اش را نداریم.\nاز تو می‌خواهم به Amaniها کمک کنی و هر کسی که ممکن است این سردابه مقدس را بی‌حرمت کند را بیندازی. بدان که این برای کسی بیرون از قبیله افتخار بزرگی است که فقط پایش را به آن‌جا بگذارد، پس با احترام با زمینش رفتار کن و پاداش می‌گیری.", c = "اثری از متهمان این‌جا نیست. باید دنبالشان به داخل برویم." }
WoWFQ[98836] = { t = "...گاهی راهِ برگشت است", o = { "پاداشت را بگیر و به Kul'amara برگرد." } }
